func TestBhvOptions060_TransportOptions_BuilderEntryPointKeepsSetValuesAndDefaults(t *testing.T) {
	t.Parallel()
	direct, err := petstore.NewTransportOptionsBuilder().Build()
	if err != nil {
		t.Fatal(err)
	}
	set, err := petstore.NewTransportOptionsBuilder().VerifySsl(false).MaxRetries(5).Build()
	if err != nil {
		t.Fatal(err)
	}
	if !direct.VerifySsl() || direct.MaxRetries() != 2 {
		t.Errorf("expected the defaults, got verifySsl %t and maxRetries %d", direct.VerifySsl(), direct.MaxRetries())
	}
	if set.VerifySsl() || set.MaxRetries() != 5 {
		t.Errorf("expected the set values, got verifySsl %t and maxRetries %d", set.VerifySsl(), set.MaxRetries())
	}
}

