func TestBhvOptions063_TransportOptions_BuiltValueIgnoresLaterBuilderChanges(t *testing.T) {
	t.Parallel()
	builder := petstore.NewTransportOptionsBuilder().DefaultHeader("X-One", "1")
	built, err := builder.Build()
	if err != nil {
		t.Fatal(err)
	}
	builder.DefaultHeader("X-Two", "2").MaxRetries(7)
	if got := built.DefaultHeaders(); len(got) != 1 || got["X-One"] != "1" {
		t.Errorf("expected the built headers to stay as built, got %v", got)
	}
	if built.MaxRetries() != 2 {
		t.Errorf("expected the built max retries to stay at 2, got %d", built.MaxRetries())
	}
}

