// secretHookTripper is a caller-supplied transport whose printed form carries a secret.
type secretHookTripper struct{}

func (secretHookTripper) RoundTrip(*http.Request) (*http.Response, error) {
	return nil, errors.New("not used")
}

func (secretHookTripper) String() string { return "hook-secret-value" }

